"""日志聚合脚本：按时间范围、字段过滤和时区跨越聚合日志条目。"""
import os
from datetime import datetime, timezone, timedelta
from typing import List, Optional, Tuple

# 默认配置
DEFAULT_TIME_RANGE = ("2024-01-01", "2024-12-31")
DEFAULT_FIELDS = ["timestamp", "level", "message"]

class LogEntry:
    """表示一条日志条目。"""
    def __init__(self, timestamp: str, level: str, message: str):
        self.timestamp = datetime.fromisoformat(timestamp.replace("Z", "+00:00"))
        self.level = level
        self.message = message

class LogAggregator:
    """日志聚合器。"""
    def __init__(self, time_range: Optional[Tuple[str, str]] = None,
                 fields: Optional[List[str]] = None):
        self.time_range = time_range or DEFAULT_TIME_RANGE
        self.fields = fields or DEFAULT_FIELDS

    def filter_by_time(self, entry: LogEntry) -> bool:
        """按时间范围过滤。"""
        start, end = self.time_range
        return start <= entry.timestamp <= end

    def filter_by_fields(self, entry: LogEntry) -> bool:
        """按字段过滤（仅检查 timestamp、level、message）。"""
        return all(field in entry.__dict__ for field in self.fields)

    def aggregate(
        self,
        entries: List[LogEntry],
        time_range: Optional[Tuple[str, str]] = None,
        fields: Optional[List[str]] = None
    ) -> List[LogEntry]:
        """聚合日志条目。"""
        return [
            entry for entry in entries
            if self.filter_by_time(entry) and self.filter_by_fields(entry)
        ]

if __name__ == "__main__":
    aggregator = LogAggregator()
    print("日志聚合器已初始化。")

"""扫描 Rust 源码里的 axum 路由，生成 Markdown 接口文档（路径、方法、参数、返回）。
"""
use axum::{http::StatusCode, routing::get, routing::post};

struct Scanner {
    source_code: String,
}

impl Scanner {
    fn new(source_code: String) -> Self {
        Scanner { source_code }
    }

    fn scan(&self) -> Vec<String> {
        let mut results = Vec::new();
        for line in self.source_code.lines() {
            if line.contains("axum::router::get") || line.contains("axum::router::post") {
                let path: String = match line.split_whitespace().next() {
                    Some(p) => p.to_string(),
                    None => "unknown".to_string(),
                };
                results.push(format!("Path: {} | Method: GET/POST", path));
            }
        }
        results
    }
}

fn main() {
    let source_code = "use axum::router::get;\nuse axum::router::post;";
    let scanner = Scanner::new(source_code);
    for result in scanner.scan() {
        println!("{}", result);
    }
}

import os
from typing import List, Tuple

class Router:
    def __init__(self):
        self.routes: List[Tuple[str, str]] = []

    def add_route(self, path: str, method: str) -> None:
        """Add a route with path and HTTP method."""
        self.routes.append((path, method))

    def resolve(self, url_path: str) -> Tuple[str, str]:
        """Resolve URL to (method, path). Returns ('NOT_FOUND', '') if no match."""
        for route in self.routes:
            if route[0] == url_path or route[0].startswith(url_path + '/'):
                return (route[1], route[0])
        return ('NOT_FOUND', '')


def main():
    router = Router()
    router.add_route('/about', 'GET')
    router.add_route('/user/<id>', 'POST')
    router.add_route('/user/profile', 'PUT')

    test_urls = ['/', '/about', '/user/123', '/user/profile']
    for url in test_urls:
        method, path = router.resolve(url)
        print(f'{url} -> {method} {path}')


if __name__ == "__main__":
    main()

