import os
import hashlib
from pathlib import Path


def get_file_hash(file_path):
    """计算文件的 SHA-256 哈希值。"""
    sha256 = hashlib.sha256()
    try:
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(8192), b''):
                sha256.update(chunk)
        return sha256.hexdigest()
    except (OSError, IOError) as e:
        print(f"错误：无法读取文件 {file_path}: {e}")
        return None


def find_duplicates(root_dir):
    """扫描目录下的重复文件（按内容哈希），返回字典。"""
    file_map = {}  # {hash: [(path, size)]}
    for path in Path(root_dir).rglob('*'):
        if path.is_file():
            h = get_file_hash(path)
            if h is None:
                continue
            entry = file_map.setdefault(h, [])
            entry.append((str(path), path.stat().st_size))
    return file_map


def main():
    """命令行入口。"""
    import argparse
    parser = argparse.ArgumentParser(description='扫描目录下的重复文件（按内容哈希）。')
    parser.add_argument('directory', help='要扫描的目录路径')
    parser.add_argument('--dry-run', action='store_true', help='仅显示结果，不实际删除。')
    parser.add_argument('--json', action='store_true', help='以 JSON 格式输出。')
    args = parser.parse_args()

    file_map = find_duplicates(args.directory)
    if not file_map:
        print("未发现重复文件。")
        return

    for hash_val, entries in file_map.items():
        if len(entries) > 1:
            print(f"哈希值: {hash_val}")
            for path, size in entries:
                print(f"  - {path} ({size} bytes)")


if __name__ == '__main__':
    main()

