"""把多行 JSON 日志按小时聚合成统计表，输出 CSV。"""
import json
from datetime import datetime, timedelta

def parse_json_log(log_text):
    """解析 JSON 字符串，返回列表。"""
    try:
        return json.loads(log_text)
    except json.JSONDecodeError as e:
        print(f"JSON 解析失败: {e}")
        return []


def group_by_hour(records):
    """按小时分组，返回字典。"""
    groups = {}
    for record in records:
        if 'timestamp' not in record or 'message' not in record:
            continue
        try:
            dt = datetime.fromisoformat(record['timestamp'])
        except ValueError:
            continue
        hour_key = dt.strftime('%Y-%m-%d %H')
        if hour_key not in groups:
            groups[hour_key] = {'count': 0, 'total_bytes': 0}
        groups[hour_key]['count'] += 1
        groups[hour_key]['total_bytes'] += len(record['message'])
    return groups


def write_csv(groups):
    """将分组结果写入 CSV。"""
    import csv
    with open('hourly_stats.csv', 'w', newline='') as f:
        writer = csv.writer(f)
        writer.writerow(['hour', 'count', 'total_bytes'])
        for hour_key in sorted(groups.keys()):
            data = groups[hour_key]
            writer.writerow([hour_key, data['count'], data['total_bytes']])


def main():
    """主入口。"""
    log_text = '''{"timestamp": "2023-01-01T10:00:00", "message": "hello"}
{"timestamp": "2023-01-01T11:00:00", "message": "world"}'''
    records = parse_json_log(log_text)
    groups = group_by_hour(records)
    write_csv(groups)

if __name__ == '__main__':
    main()

import os
import re
from typing import List, Tuple

# ---------- 数据结构 ----------
def _is_valid_url(url: str) -> bool:
    """判断 URL 是否合法（以 http:// 或 https:// 开头）。"""
    return url.startswith("http://") or url.startswith("https://")

class DocItem:
    """文档项：包含路径、标题和内容。"""
    def __init__(self, path: str, title: str, content: str):
        self.path = path
        self.title = title
        self.content = content

# ---------- 核心函数 ----------
def generate_docs(items: List[DocItem]) -> List[Tuple[str, str]]:
    """生成文档列表，返回 (路径, 标题) 元组。"""
    result = []
    for item in items:
        if _is_valid_url(item.path):
            result.append((item.path, item.title))
    return result

# ---------- 入口 ----------
def main():
    """主函数：读取文件，生成文档。"""
    input_path = "/tmp/docs.txt"
    output_path = "/tmp/output.txt"
    items = []
    with open(input_path, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            parts = line.split(",")
            if len(parts) != 3:
                continue
            path, title, content = parts[0].strip(), parts[1].strip(), parts[2].strip()
            items.append(DocItem(path, title, content))
    docs = generate_docs(items)
    with open(output_path, "w", encoding="utf-8") as f:
        for path, title in docs:
            f.write(f"{path}\t{title}\n")

if __name__ == "__main__":
    main()

"""扫描目录下的重复文件（按内容哈希），支持 --dry-run 与 --json 输出。"""
import argparse
import hashlib
import os
import sys

def compute_hash(file_path):
    """计算文件的 SHA-256 哈希值。"""
    sha256 = hashlib.sha256()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            sha256.update(chunk)
    return sha256.hexdigest()


def find_duplicates(directory):
    """查找目录下内容相同的文件对。返回字典：{hash: [file_path]}。"""
    hash_map = {}
    for root, _, files in os.walk(directory):
        for file_name in files:
            file_path = os.path.join(root, file_name)
            try:
                h = compute_hash(file_path)
            except (OSError, IOError) as e:
                print(f"警告: 无法读取 {file_path}: {e}", file=sys.stderr)
                continue
            hash_map.setdefault(h, []).append(file_path)
    return hash_map


def main():
    parser = argparse.ArgumentParser(description='扫描目录下的重复文件（按内容哈希）。')
    parser.add_argument('directory', help='要扫描的目录路径')
    parser.add_argument('--dry-run', action='store_true', help='仅显示结果，不实际删除。')
    parser.add_argument('--json', action='store_true', help='以 JSON 格式输出。')
    args = parser.parse_args()

    if not os.path.isdir(args.directory):
        print(f"错误: {args.directory} 不是有效目录", file=sys.stderr)
        sys.exit(1)

    result = find_duplicates(args.directory)
    duplicates = {h: paths for h, paths in result.items() if len(paths) > 1}

    if args.json:
        print(json.dumps({'duplicates': duplicates}, indent=2))
    else:
        for h, paths in duplicates.items():
            print(f"哈希 {h}:")
            for p in paths:
                print(p)


if __name__ == '__main__':
    main()

