import threading
from typing import Optional, List

class UserService:
    def __init__(self):
        self.users = {}
        self.lock = threading.Lock()

    def create_user(self, name: str, email: str) -> bool:
        """创建用户，若已存在则返回 False。"""
        with self.lock:
            if name in self.users or email in self.users:
                return False
            self.users[name] = {"name": name, "email": email}
            return True

    def update_user(self, user_id: str, name: Optional[str], email: Optional[str]) -> bool:
        """更新用户信息，仅允许修改非空字段。"""
        with self.lock:
            if user_id not in self.users:
                return False
            if name is None and email is None:
                return False
            if name is not None:
                self.users[user_id]["name"] = name
            if email is not None:
                self.users[user_id]["email"] = email
            return True

    def delete_user(self, user_id: str) -> bool:
        """删除用户。"""
        with self.lock:
            if user_id in self.users:
                del self.users[user_id]
                return True
            return False

