LOG_FORMAT = "%Y-%m-%d %H:%M:%S [LEVEL] message"


def parse_log_line(line: str) -> Tuple[str, str]:
    """解析单行日志，返回（时间戳，消息）。"""
    # 跳过空行和注释行
    if not line.strip() or line.startswith('#'):
        return None, None

    try:
        # 按分隔符拆分：时间戳、级别、消息
        parts = line.split(' ', 2)
