            return None, None
        timestamp, level, message = parts[0], parts[1], ' '.join(parts[2:])
        return timestamp.strip(), message.strip()
    except Exception:
        # 遇到乱码或格式错误时返回 None
        return None, None


def filter_garbled_lines(log_content: str) -> List[Tuple[str, str]]:
    """过滤掉包含乱码字符的行，只保留有效日志行。"""
    valid_logs = []
    for line in log_content.split('\n'):
