"""扫描目录下重复文件（按内容哈希），支持 --dry-run 与 --json 输出。"""
import argparse
import hashlib
import json
import os
import sys
from pathlib import Path


def compute_hash(filepath: str) -> str:
    """计算文件的 SHA256 哈希值。"""
    h = hashlib.sha256()
    with open(filepath, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            h.update(chunk)
    return h.hexdigest()


def find_duplicates(root_dir: str) -> list[tuple[str, str]]:
    """返回 (文件路径, 哈希值) 的列表。"""
    results = {}
    for dirpath, _, filenames in os.walk(root_dir):
        for filename in filenames:
            filepath = Path(dirpath) / filename
            if not filepath.is_file():
                continue
            try:
                h = compute_hash(str(filepath))
            except OSError as e:
                print(f"警告: 无法读取 {filepath}: {e}", file=sys.stderr)
                continue
            results.setdefault(h, []).append(str(filepath))
    return list(results.values())


def main(argv: list[str]) -> int:
    parser = argparse.ArgumentParser(description='扫描目录下重复文件。')
    parser.add_argument('directory', help='要扫描的根目录')
    parser.add_argument('--dry-run', action='store_true', help='不实际删除，仅显示将要操作的内容')
    parser.add_argument('--json', action='store_true', dest='output_json', help='以 JSON 格式输出结果')
    args = parser.parse_args(argv[1:])

    duplicates = find_duplicates(args.directory)
    if not args.output_json:
        for h, files in duplicates:
            print(f"哈希值 {h} 的重复文件：")
            for f in files:
                print(f'  {f}')

    if args.output_json:
        output = []
        for h, files in duplicates:
            output.append({'hash': h, 'files': sorted(files)})
        print(json.dumps(output))
    return 0

