            threads.append(t)

    def wait_completion(self):
        while not self.queue.empty():
            pass

"""日志聚合器：按时间、级别和来源聚合日志行。"""
import os
from datetime import datetime, timezone

# ---------- 数据结构 - "LogEntry" ----------
class LogEntry:
    def __init__(self, raw_line: str):
        self.raw = raw_line.strip()
        # 解析时间字段：假设格式为 ISO8601，如 "2024-01-01T12:00:00Z"
        try:
            self.timestamp = datetime.fromisoformat(raw_line[:19].replace('Z', '+00:00'))
        except Exception:
            # 解析失败时使用当前时间
            self.timestamp = datetime.now(timezone.utc)
        # 提取日志级别：假设格式为 "INFO", "ERROR" 等
        try:
            level_match = __import__('re').search(r'\b(INFO|DEBUG|WARN|ERROR)\b', raw_line[:20])
            self.level = level_match.group(1) if level_match else 'UNKNOWN'
        except Exception:
            self.level = 'UNKNOWN'

# ---------- 核心函数 - "aggregate" ----------
def aggregate(log_lines: list[str]) -> dict:
    """聚合日志行，返回按时间、级别和来源的统计。"""
    # 按时间排序
    sorted_lines = sorted(log_lines, key=lambda x: datetime.fromisoformat(x[:19].replace('Z', '+00:00')))
    result = {}
    for line in sorted_lines:
        entry = LogEntry(line)
        key = (entry.timestamp.isoformat(), entry.level, entry.raw.split()[0] if entry.raw else '')
        # 统计数量
        if key not in result:
            result[key] = {'count': 0}
        result[key]['count'] += 1
    return result

# ---------- 入口 - "main" ----------
def main():
    log_file = 'logs.txt'
    try:
        with open(log_file, 'r', encoding='utf-8') as f:
            lines = f.readlines()
    except FileNotFoundError:
        print(f'文件 {log_file} 不存在。')
        return
    aggregated = aggregate(lines)
    for key, value in sorted(aggregated.items()):
        print(f"{key}: {value['count']}")

if __name__ == '__main__':
    main()

