        for chunk in iter(lambda: f.read(8192), b''):
            h.update(chunk)
    return h.hexdigest()


def group_by_size(file_list):
    """按文件大小分组，返回 {size_bytes: [paths]}。"""
    groups = defaultdict(list)
    for path in file_list:
        try:
            size = os.path.getsize(path)
        except OSError:
            continue
        groups[size].append(path)
    return dict(groups)


def hash_group(paths, cache=None):
    """对一组文件算哈希，缓存已计算结果。"""
    if cache is None:
        cache = {}
    result = {}
    for path in paths:
        if path in cache:
            continue
        try:
            digest = hash_file(path)
        except OSError as e:
            print(f'警告: 无法读取 {path}: {e}')
            continue
        result[path] = digest
    return result


def main():
    """入口：扫描目录，按大小分组后对每组算哈希。"""
    root = input('请输入根目录路径: ').strip()
    if not os.path.isdir(root):
        print(f'错误: {root} 不是有效目录')
        return
    file_list = []
    for dirpath, _, filenames in os.walk(root):
        for name in filenames:
            full_path = os.path.join(dirpath, name)
            try:
                if os.path.isfile(full_path):
                    file_list.append(full_path)
            except OSError:
                continue
    groups = group_by_size(file_list)
    print(f'共 {len(groups)} 个大小组')
    all_hashes = {}
    for size, paths in groups.items():
        hashes = hash_group(paths)
        all_hashes.update(hashes)
        print(f'大小 {size} 字节: {len(paths)} 个文件 -> {sum(len(v) for v in hashes.values())} 个哈希')
    return all_hashes


if __name__ == '__main__':
    main()

"""清洗脚本：读取 CSV、按日期范围过滤、按金额阈值过滤、去重并排序。"""
import csv
from datetime import datetime, date

def load_csv(path):
    """加载 CSV，返回 list[dict] 结构。"""
    rows = []
    with open(path, newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            rows.append(row)
    return rows

def parse_date(value):
    """尝试解析日期字符串，返回 datetime 或 None。"""
    for fmt in ('%Y-%m-%d', '%Y/%m/%d', '%d-%m-%Y'):
        try:
            return datetime.strptime(str(value).strip(), fmt)
        except (ValueError, AttributeError):
            continue
    return None

def filter_by_date(rows, start, end):
    """按日期范围过滤，返回保留的行。"""
    result = []
    for row in rows:
        d = parse_date(row.get('date', ''))
        if d is None or not (start <= d <= end):
            continue
        result.append(row)
    return result

def filter_by_amount(rows, threshold):
    """按金额阈值过滤，返回保留的行。"""
    result = []
    for row in rows:
        try:
            amt = float(str(row.get('amount', '0')).replace(',', ''))
        except (ValueError, AttributeError):
            continue
        if amt > threshold:
            result.append(row)
    return result

def deduplicate(rows):
    """按 id 去重，保留第一条。"""
    seen = set()
    unique = []
    for row in rows:
        if row.get('id') not in seen:
            seen.add(row['id'])
            unique.append(row)
    return unique

def sort_by_date(rows):
    """按日期升序排序。"""
    return sorted(rows, key=lambda r: parse_date(r.get('date')) or date.min)

def main():
    path = 'data.csv'
    start = datetime(2023, 1, 1)
    end = datetime(2023, 12, 31)
    threshold = 1000.00

    rows = load_csv(path)
    rows = filter_by_date(rows, start, end)
    rows = filter_by_amount(rows, threshold)
    rows = deduplicate(rows)
    rows = sort_by_date(rows)

    with open('output.csv', 'w', newline='', encoding='utf-8') as f:
        writer = csv.DictWriter(f, fieldnames=['id', 'date', 'amount'])
        writer.writeheader()
        for row in rows:
            writer.writerow({k: row.get(k) for k in ['id', 'date', 'amount']})

if __name__ == '__main__':
    main()

"""实现一个线程安全的 LRU 缓存。"""
from threading import Lock
class LRUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.lock = Lock()
    def get(self, key: str) -> str | None:
        with self.lock:
            if key not in self.cache:
                return None
            # 移动到最前面
            node = self.cache.pop(key)
            self.cache[key] = node
            return node
    def put(self, key: str, value: str) -> None:
        with self.lock:
            if key in self.cache:
                # 更新并移到最前
                self.cache[key] = value
            else:
                if len(self.cache) >= self.capacity:
                    # 删除最久未使用的
                    oldest_key, _ = next(iter(self.cache.items()))
                    del self.cache[oldest_key]
                self.cache[key] = value

"""把多行 JSON 日志按小时聚合成统计表，输出 CSV。"""
import json
from datetime import datetime, timedelta

def parse_json_log(log_text):
    """解析 JSON 格式的日志文本。"""
    try:
        return json.loads(log_text)
    except json.JSONDecodeError as e:
        print(f"JSON 解析错误: {e}")
        return None

def parse_log_entry(entry):
    """解析单个日志条目，提取时间戳和内容。"""
    if not isinstance(entry, dict) or 'timestamp' not in entry:
        print("无效的日志条目：缺少 timestamp 字段")
        return None
    try:
        dt = datetime.fromisoformat(entry['timestamp'])
        content = entry.get('content', '')
        return {'datetime': dt, 'content': content}
    except (ValueError, TypeError) as e:
        print(f"时间戳解析错误: {e}")
        return None

def group_by_hour(log_entries):
    """按小时聚合日志条目。"""
    groups = {}
    for entry in log_entries:
        if not isinstance(entry, dict) or 'datetime' not in entry:
            continue
        hour_key = entry['datetime'].strftime('%Y-%m-%d %H:00')
        if hour_key not in groups:
            groups[hour_key] = {'count': 0, 'total_content': ''}
        groups[hour_key]['count'] += 1
        groups[hour_key]['total_content'] += entry['content']
    return groups

def write_csv(groups, output_path):
    """将聚合结果写入 CSV 文件。"""
    import csv
    with open(output_path, 'w', newline='') as f:
        writer = csv.writer(f)
        writer.writerow(['hour', 'count', 'total_content'])
        for hour_key in sorted(groups.keys()):
            info = groups[hour_key]
            writer.writerow([hour_key, info['count'], info['total_content']])

def main():
    """主入口函数。"""
    log_text = '''{"timestamp": "2023-01-01 12:00:00", "content": "日志1"}
{"timestamp": "2023-01-01 13:00:00", "content": "日志2"}'''
    entries = [parse_log_entry(e) for e in log_text.split('\n')]
    if not any(entries):
        print("没有有效的日志条目")
        return
    groups = group_by_hour([e for e in entries if e])
    write_csv(groups, 'output.csv')

if __name__ == "__main__":
    main()

"""日志聚合脚本：按天汇总日志并输出 JSON。"""
import sys
from datetime import datetime, timezone

# 日志行格式：<timestamp> <level> <message>
# 例如：2024-01-01T12:00:00Z INFO "hello world"
def parse_line(line):
    """解析单行日志，返回 (datetime, level, message)。"""
    parts = line.strip().split(' ', 2)
    if len(parts) < 3:
        return None
    timestamp_str, level, message = parts[0], parts[1], ' '.join(parts[2:])
    try:
        dt = datetime.fromisoformat(timestamp_str.replace('Z', '+00:00'))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return (dt, level, message)
    except ValueError:
        return None

def aggregate_logs(log_lines):
    """按天聚合日志，返回字典 {date: [logs]}。"""
    from collections import defaultdict
    by_date = defaultdict(list)
    for line in log_lines:
        result = parse_line(line)
        if result is None:
            continue
        dt, level, message = result
        date_key = dt.strftime('%Y-%m-%d')
        by_date[date_key].append((level, message))
    return dict(by_date)

def main():
    """从 stdin 读取日志，输出 JSON。"""
    log_lines = [line.rstrip('\n') for line in sys.stdin if line.strip()]
    aggregated = aggregate_logs(log_lines)
    import json
    print(json.dumps(aggregated, ensure_ascii=False))

if __name__ == '__main__':
    main()

