"""扫描目录下重复文件（按内容哈希），支持 --dry-run 与 --json 输出。"""
import argparse
import hashlib
import os
from pathlib import Path

def get_file_hash(filepath):
    """计算文件的 SHA256 哈希值。"""
    h = hashlib.sha256()
    with open(filepath, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            h.update(chunk)
    return h.hexdigest()


def find_duplicates(root_dir, dry_run=False, json_output=False):
    """查找重复文件，返回 (hash, [filepaths])。"""
    root = Path(root_dir).resolve()
    files = {}
    for path in root.rglob('*'):
        if path.is_file():
            h = get_file_hash(path)
            files.setdefault(h, []).append(str(path))

    duplicates = [(h, paths) for h, paths in files.items() if len(paths) > 1]
    return duplicates


def main():
    parser = argparse.ArgumentParser(description='扫描目录下重复文件（按内容哈希）。')
    parser.add_argument('directory', help='要扫描的根目录')
    parser.add_argument('--dry-run', action='store_true', help='不实际删除，仅显示将要操作的文件。')
    parser.add_argument('--json', action='store_true', help='以 JSON 格式输出结果。')

    args = parser.parse_args()

    duplicates = find_duplicates(args.directory, dry_run=args.dry_run, json_output=args.json)

    if not duplicates:
        print('未发现重复文件。')
        return

    for h, paths in duplicates:
        print(f"哈希: {h}")
        for p in paths:
            print(p)


if __name__ == '__main__':
    main()

