"""生成文档的脚本：路由带路径参数、嵌套路由、同名方法不同路径。"""
import os
from typing import List, Tuple, Dict

class DocGenerator:
    def __init__(self):
        self.routes = []

    def add_route(self, path: str, method: str, handler: str) -> None:
        """添加路由。"""
        self.routes.append({"path": path, "method": method, "handler": handler})

    def match_route(
        self,
        path: str,
        method: str,
        *args: Tuple[str, ...]
    ) -> List[Dict]:
        """匹配路由，返回所有匹配的路由。"""
        matches = []
        for route in self.routes:
            if route["method"] == method and route["path"] == path:
                matches.append(route)
        return matches

    def generate_docs(self) -> List[Dict]:
        """生成文档。"""
        docs = []
        for route in self.routes:
            doc = {
                "path": route["path"],
                "method": route["method"],
                "handler": route["handler"]
            }
            docs.append(doc)
        return docs


def main() -> None:
    generator = DocGenerator()
    generator.add_route("/user", "GET", "get_user")
    generator.add_route("/user/<id>", "GET", "get_user_by_id")
    generator.add_route("/user", "POST", "create_user")
    generator.add_route("/user/<id>", "PUT", "update_user")

    docs = generator.generate_docs()
    for doc in docs:
