"""扫描目录下重复文件，支持 --dry-run 与 --json 输出。"""
import argparse
import hashlib
import os
import sys
from pathlib import Path


def compute_hash(path: str) -> str:
    """计算文件的 SHA256 哈希值。"""
    h = hashlib.sha256()
    with open(path, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            h.update(chunk)
    return h.hexdigest()


def find_duplicates(root_dir: str) -> list[tuple[str, str]]:
    """返回 (文件路径, 哈希值) 的列表，按哈希分组。"""
    root = Path(root_dir)
    files = []
    for path in root.rglob('*'):
        if path.is_file():
            try:
                files.append((str(path), compute_hash(str(path))))
            except OSError as e:
                print(f"警告: 无法读取 {path}: {e}", file=sys.stderr)
    return files


def main() -> None:
    parser = argparse.ArgumentParser(description='扫描目录下重复文件。')
    parser.add_argument('directory', help='要扫描的根目录')
    parser.add_argument('--dry-run', action='store_true', help='不实际删除，仅显示将要操作的内容')
    parser.add_argument('--json', action='store_true', help='以 JSON 格式输出结果')
    args = parser.parse_args()

    files = find_duplicates(args.directory)
    by_hash: dict[str, list[Path]] = {}
    for path_str, h in files:
        by_hash.setdefault(h, []).append(Path(path_str))

    duplicates = [(p, h) for h, paths in by_hash.items() if len(paths) > 1]

    if args.json:
        result = [{'path': str(p), 'hash': h} for p, h in duplicates]
        print(result)
    else:
        for path_str, h in duplicates:
            print(f"{path_str}: {h}")


if __name__ == '__main__':
    main()

"""测试工具：验证目录存在性、是否为空、是否存在同名不同内容以及真重复文件。"""
import os
import sys
from pathlib import Path

def check_directory_exists(path):
    """检查指定路径是否存在且非空。"""
    return os.path.isdir(path) and os.listdir(path)

def is_empty_directory(path):
    """判断目录是否为空。"""
    try:
        return len(os.listdir(path)) == 0
    except FileNotFoundError:
        return False

def has_same_name_diff_content(path1, path2):
    """检查两个路径是否存在同名但内容不同的文件。"""
    if not os.path.isfile(path1) or not os.path.isfile(path2):
        return False
    try:
        with open(path1, 'rb') as f1, open(path2, 'rb') as f2:
            return f1.read() != f2.read()
    except FileNotFoundError:
        return False

def has_true_duplicate_files(dir_path):
    """检查目录中是否存在内容完全相同的文件对。"""
    try:
        files = os.listdir(dir_path)
    except FileNotFoundError:
        return False
    seen = {}
    for f in files:
        full_path = os.path.join(dir_path, f)
        if not os.path.isfile(full_path):
            continue
        with open(full_path, 'rb') as fp:
            content = fp.read()
        seen[content] = seen.get(content, 0) + 1
    return any(count > 1 for count in seen.values())

"""优化大文件哈希计算：先按大小分组，再对同尺寸文件算哈希，避免全量读取。"""
import os
from collections import defaultdict

def group_by_size(file_paths):
    """按文件大小分组，返回 {size_bytes: [paths]} 的字典。"""
    groups = defaultdict(list)
    for path in file_paths:
        try:
            size = os.path.getsize(path)
        except OSError:
            continue
        groups[size].append(path)
    return dict(groups)


def hash_file_group(group):
    """对一组同尺寸文件计算哈希。"""
    hashes = []
    for path in group:
        try:
            h = hashlib.md5()
            with open(path, 'rb') as f:
                while True:
                    chunk = f.read(8192)
                    if not chunk:
                        break
                    h.update(chunk)
            hashes.append(h.hexdigest())
        except OSError:
            continue
    return hashes


def main():
    """入口：从 stdin 读文件路径列表，输出分组哈希。"""
    import sys
    file_paths = [line.strip() for line in sys.stdin if line.strip()]
    groups = group_by_size(file_paths)
    all_hashes = []
    for size, paths in sorted(groups.items()):
        print(f"大小 {size} bytes 的文件数: {len(paths)}")
        hashes = hash_file_group(paths)
        all_hashes.extend(hashes)
    print("\n所有哈希:")
    for h in all_hashes:
        print(h)


if __name__ == "__main__":
    main()

