"""清洗数据：处理空值、日期格式、金额千分位。"""
import re
from datetime import datetime

def clean_data(data):
    """清洗单行数据。"""
    # 1. 去除首尾空白
    line = data.strip()

    # 2. 处理空值：全空或只有表头直接返回 None
    if not re.match(r'^\s*$', line):
        return None

    # 3. 提取字段
    fields = [f for f in line.split('|')]

    # 4. 处理日期格式：统一为 YYYY-MM-DD
    date_str = fields[1] if len(fields) > 1 else None
    if date_str:
        try:
            dt = datetime.strptime(date_str, '%Y-%m-%d')
            fields[1] = dt.strftime('%Y-%m-%d')
        except ValueError:
            # 尝试多种格式
            for fmt in ['%d/%m/%Y', '%m/%d/%Y']:
                try:
                    dt = datetime.strptime(date_str, fmt)
                    fields[1] = dt.strftime('%Y-%m-%d')
                    break
                except ValueError:
                    continue

    # 5. 处理金额：去除千分位，统一为两位小数
    amount_str = fields[2] if len(fields) > 2 else None
    if amount_str:
        try:
            amount = float(amount_str.replace(',', ''))
            fields[2] = f'{amount:.2f}'
        except ValueError:
            return None

    # 6. 处理备注：去除首尾空格
    remark = fields[3] if len(fields) > 3 else None
    if remark:
        remark = remark.strip()

    return '|'.join(fields)


def main():
    """主入口。"""
    # 读取文件
    with open('input.txt', 'r') as f:
        lines = f.readlines()

    # 清洗每行数据
    cleaned_lines = [clean_data(line) for line in lines]

    # 写入输出文件
    with open('output.txt', 'w') as f:
        for line in cleaned_lines:
            if line is not None:
                f.write(line + '\n')

if __name__ == '__main__':
    main()

