"""日志聚合脚本：读取本地日志文件，按时间戳和级别分组并输出汇总统计。"""
import os
from datetime import datetime

# 数据结构定义
class LogEntry:
    """表示一条日志记录，包含时间、级别和内容。"""
    def __init__(self, timestamp: str, level: str, message: str):
        self.timestamp = timestamp
        self.level = level
        self.message = message

# 核心函数：读取并解析日志文件
def parse_log_file(filepath: str) -> list[LogEntry]:
    """从本地日志文件中读取并解析为 LogEntry 列表。处理乱码行和空行。"""
    entries = []
    with open(filepath, 'r', encoding='utf-8') as f:
        for line in f:
            # 跳过空行
            if not line.strip():
                continue
            # 尝试解析日志行，忽略无法解析的行
            try:
                parts = line.split(' ', 2)
                timestamp, level, message = parts[0], parts[1], ' '.join(parts[2:])
                entries.append(LogEntry(timestamp, level, message))
            except (IndexError, ValueError):
                # 忽略格式错误的行
                continue
    return entries

# 核心函数：按时间分组并统计级别分布
def aggregate_logs(entries: list[LogEntry]) -> dict:
    """将日志条目按时间分组，返回每个时间段的级别统计。"""
    # 按时间戳排序
    sorted_entries = sorted(entries, key=lambda e: e.timestamp)
    result = {}
    current_time = None
    for entry in sorted_entries:
        if entry.timestamp != current_time:
            if current_time is not None:
                # 统计当前时间段的级别分布
                level_counts = {}
                for e in entries:
                    if e.timestamp == current_time:
                        level_counts[e.level] = level_counts.get(e.level, 0) + 1
                result[current_time] = level_counts
            current_time = entry.timestamp
    # 处理最后一个时间段
    if current_time is not None:
        level_counts = {}
        for e in entries:
            if e.timestamp == current_time:
                level_counts[e.level] = level_counts.get(e.level, 0) + 1
        result[current_time] = level_counts
    return result

# 主入口：读取文件、解析、聚合并输出
def main():
    """程序入口：从本地日志文件读取，解析并输出汇总统计。"""
    filepath = 'logs.txt'
    if not os.path.exists(filepath):
        print(f'错误：文件 {filepath} 不存在')
        return
    entries = parse_log_file(filepath)
    if not entries:
        print('日志文件为空或无有效记录')
        return
    result = aggregate_logs(entries)
    for time, levels in result.items():
        total = sum(levels.values())
        print(f'时间: {time}, 级别分布: {levels}, 总计: {total}')

if __name__ == '__main__':
    main()

import os
