"""扫描目录下的重复文件（按内容哈希），支持 --dry-run 与 --json 输出。"""
import argparse
import hashlib
import os
import sys
from pathlib import Path


def compute_hash(filepath):
    """计算文件的 SHA-256 哈希值。"""
    sha256 = hashlib.sha256()
    try:
        with open(filepath, 'rb') as f:
            for chunk in iter(lambda: f.read(8192), b''):
                sha256.update(chunk)
        return sha256.hexdigest()
    except (OSError, IOError) as e:
        print(f"[error] 无法读取文件 {filepath}: {e}", file=sys.stderr)
        sys.exit(1)


def collect_files(directory):
    """收集目录下所有非隐藏文件的完整路径。"""
    files = []
    for root, dirs, names in os.walk(directory):
        # 跳过以 . 开头的隐藏目录
        dirs[:] = [d for d in dirs if not d.startswith('.')]
        for name in names:
            if name.startswith('.'):
                continue
            files.append(Path(root) / name)
    return files


def find_duplicates(files, dry_run=False):
    """找出重复文件（按内容哈希）。"""
    hash_map = {}
    for filepath in files:
        try:
            h = compute_hash(filepath)
        except Exception as e:
            print(f"[error] 跳过无法计算哈希的文件 {filepath}: {e}", file=sys.stderr)
            continue
        hash_map.setdefault(h, []).append(str(filepath))
    duplicates = [(h, paths) for h, paths in hash_map.items() if len(paths) > 1]
    return duplicates


def main():
    parser = argparse.ArgumentParser(
        description='扫描目录下的重复文件（按内容哈希），支持 --dry-run 与 --json 输出。'
    )
    parser.add_argument('directory', help='要扫描的目录路径')
    parser.add_argument('--dry-run', action='store_true', help='仅显示重复文件，不实际删除')
    parser.add_argument('--json', action='store_true', help='以 JSON 格式输出结果')

    args = parser.parse_args()

    if not os.path.isdir(args.directory):
        print(f"[error] 目录不存在: {args.directory}", file=sys.stderr)
        sys.exit(1)

    files = collect_files(args.directory)
    duplicates = find_duplicates(files, dry_run=args.dry_run)

    if args.json:
        import json
        output = []
        for h, paths in duplicates:
            output.append({'hash': h, 'files': paths})
        print(json.dumps(output))
    else:
        if not duplicates:
            print('未发现重复文件。')
        for h, paths in duplicates:
            print(f"哈希: {h}")
            for path in paths:
                print(path)


if __name__ == '__main__':
    main()

