"""清洗脚本：处理 CSV/TSV 数据，清理空值、日期格式、金额千分位。"""
import os
from typing import List, Tuple, Optional

# 定义数据结构
class DataRow:
    def __init__(self, row: List[str]):
        self.original = row
        self.cleaned = []

    def is_empty(self) -> bool:
        return all(c.strip() == "" for c in self.original)

# 定义清洗函数
class Cleaner:
    def __init__(self, source: str):
        self.source = source

    # 读取数据
    def read_data(self) -> List[DataRow]:
        rows = []
        with open(self.source, "r", encoding="utf-8") as f:
            header = f.readline().strip()
            for line in f:
                row = line.strip().split("|")
                if not row or all(c == "" for c in row):
                    continue
                rows.append(DataRow(row))
        return rows

    # 清洗空值
    def clean_empty(self, row: DataRow) -> DataRow:
        cleaned = []
        for val in row.original:
            if val.strip() == "":
                cleaned.append("")
            else:
                cleaned.append(val.strip())
        return DataRow(cleaned)

    # 清洗日期格式
    def clean_date(self, row: DataRow) -> DataRow:
        for i in range(len(row.original)):
            if "date" in row.original[i].lower():
                val = row.original[i]
                try:
                    from datetime import datetime
                    dt = datetime.strptime(val, "%Y-%m-%d")
                    row.original[i] = dt.strftime("%Y-%m-%d")
                except ValueError:
                    pass
        return row

    # 清洗金额千分位
    def clean_amount(self, row: DataRow) -> DataRow:
        for i in range(len(row.original)):
            if "amount" in row.original[i].lower():
                val = row.original[i]
                try:
                    from decimal import Decimal
                    cleaned = str(Decimal(val).quantize("0.01", rounding="ROUND_HALF_UP"))
                    row.original[i] = cleaned
                except Exception:
                    pass
        return row

    # 执行清洗
    def clean(self, rows: List[DataRow]) -> List[DataRow]:
        for row in rows:
            row = self.clean_empty(row)
            row = self.clean_date(row)
            row = self.clean_amount(row)
        return rows

# 入口函数
