"""实现一个多线程工作进程，支持任务队列和结果回调。"""
import threading
from typing import List, Callable, Any

class Task:
    def __init__(self, data: Any):
        self.data = data
        self.result: Any = None

class Worker:
    def __init__(self, task_queue: List[Task], callback: Callable[[Any], None]):
        self.task_queue = task_queue
        self.callback = callback
        self.lock = threading.Lock()

    def run(self):
        while True:
            with self.lock:
                if not self.task_queue:
                    break
                task = self.task_queue.pop(0)
            try:
                result = self.callback(task.data)
            except Exception as e:
                print(f"Error: {e}")
            with self.lock:
                task.result = result

if __name__ == "__main__":
    def callback(data):
        print(f"Processed: {data}")

    tasks = [Task(1), Task(2), Task(3)]
    worker = Worker(tasks, callback)
    worker.run()

