"""日志聚合脚本：读取多文件日志，按时间戳排序后输出汇总。"""
import os
from datetime import datetime

def parse_log_line(line):
    """解析单行日志，返回 (timestamp, level, message)。"""
    parts = line.strip().split(' ', 2)
    if len(parts) < 3:
        return None
    try:
        ts = datetime.strptime(parts[0], '%Y-%m-%d %H:%M:%S')
    except ValueError:
        return None
    level = parts[1]
    message = ''.join(parts[2:])
    return (ts, level, message)

def read_logs(filepath):
    """读取文件，返回所有解析后的日志记录。"""
    records = []
    with open(filepath, 'r', encoding='utf-8') as f:
        for line in f:
            result = parse_log_line(line)
            if result is not None:
                records.append(result)
    return records

def aggregate_logs(logs):
    """按时间戳排序并去重，返回汇总列表。"""
    sorted_logs = sorted(logs, key=lambda x: x[0])
    unique_records = []
    for record in sorted_logs:
        if not unique_records or unique_records[-1][0] != record[0]:
            unique_records.append(record)
    return unique_records

def main():
    """主入口：读取所有日志文件并输出汇总。"""
    log_dir = 'logs'
    all_logs = []
    for filename in os.listdir(log_dir):
        filepath = os.path.join(log_dir, filename)
        if os.path.isfile(filepath):
            records = read_logs(filepath)
            all_logs.extend(records)
    aggregated = aggregate_logs(all_logs)
    for record in aggregated:
        print(f"{record[0].strftime('%Y-%m-%d %H:%M:%S')} {record[1]} {record[2]}")

if __name__ == '__main__':
    main()

"""扫描目录下重复文件，支持 --dry-run 与 --json 输出。"""
import argparse
import hashlib
import os
import sys
from pathlib import Path


def compute_hash(filepath: str) -> str:
    """计算文件的 SHA-256 哈希值。"""
    sha256 = hashlib.sha256()
    with open(filepath, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            sha256.update(chunk)
    return sha256.hexdigest()


def find_duplicates(root_dir: str) -> list[tuple[str, str]]:
    """返回 (文件路径, 哈希值) 的列表，按哈希分组。"""
    hashes = {}
    for dirpath, _, filenames in os.walk(root_dir):
        for filename in filenames:
            filepath = Path(dirpath) / filename
            if not filepath.is_file():
                continue
            h = compute_hash(str(filepath))
            hashes.setdefault(h, []).append(str(filepath))
    return [(h, paths) for h, paths in hashes.items() if len(paths) > 1]


def main(argv: list[str]) -> int:
    """命令行入口。"""
    parser = argparse.ArgumentParser(description='扫描目录下重复文件')
    parser.add_argument('directory', help='要扫描的根目录')
    parser.add_argument('--dry-run', action='store_true', help='不实际删除，仅显示将要操作的内容')
    parser.add_argument('--json', action='store_true', help='以 JSON 格式输出结果')
    args = parser.parse_args(argv)

    root_dir = Path(args.directory).resolve()
    if not root_dir.is_dir():
        print(f'错误：{root_dir} 不是目录。', file=sys.stderr)
        return 1

    duplicates = find_duplicates(str(root_dir))
    if args.json:
        import json
        result = []
        for h, paths in duplicates:
            result.append({'hash': h, 'paths': paths})
        print(json.dumps(result, indent=2, ensure_ascii=False))
    else:
        for h, paths in duplicates:
            print(f'哈希: {h}')
            for p in paths:
                print(p)

    return 0


if __name__ == '__main__':
    sys.exit(main([]))

