"""优化大文件哈希计算：按大小分组后只对同尺寸文件算哈希。"""
import os
from collections import defaultdict

def hash_file(path):
    """读取并返回文件的 MD5 哈希值（字符串）。"""
    h = hashlib.md5()
    with open(path, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            h.update(chunk)
    return h.hexdigest()


def group_by_size(file_paths):
    """按文件大小分组，返回 {size_bytes: [paths]} 的字典。"""
    groups = defaultdict(list)
    for p in file_paths:
        try:
            sz = os.path.getsize(p)
        except OSError:
            continue
        groups[sz].append(p)
    return dict(groups)


def hash_group(paths):
    """对一组路径计算哈希，返回 {path: hash} 的字典。"""
    result = {}
    for p in paths:
        try:
            result[p] = hash_file(p)
        except OSError:
            continue
    return result


def main():
    """主入口：扫描当前目录下所有 .txt 文件，按大小分组后计算哈希。"""
    import sys
    dir_path = sys.argv[1] if len(sys.argv) > 1 else '.'
    txt_files = [f for f in os.listdir(dir_path) if f.endswith('.txt')]
    file_paths = [os.path.join(dir_path, f) for f in txt_files]

    groups = group_by_size(file_paths)
    all_hashes = {}
    for size, paths in groups.items():
        print(f'处理大小为 {size} bytes 的文件组：{len(paths)} 个')
        all_hashes.update(hash_group(paths))

    import json
    with open('hash_result.json', 'w') as f:
        json.dump(all_hashes, f, indent=2)


if __name__ == '__main__':
    main()

"""清洗脚本：读取 CSV、按日期范围过滤、去除重复行、清理空值与格式化金额。"""
import csv
from datetime import date, datetime

# 1. 数据结构定义
class DataRow:
    def __init__(self, row):
        self.date = row.get('date')
        self.name = row.get('name')
        self.value = row.get('value')

# 2. 核心函数：清洗数据

def clean_data(csv_path: str) -> list:
    """读取 CSV 并返回清洗后的行列表。"""
    cleaned_rows = []
    with open(csv_path, newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f)

        for row in reader:
            # 跳过空值行
            if not any(row.values()):
                continue

            date_str = row.get('date')
            value_str = row.get('value')

            # 日期范围过滤：2023-01-01 至 2024-12-31
            try:
                date_obj = datetime.strptime(date_str, '%Y-%m-%d').date()
                if not (date(2023, 1, 1) <= date_obj <= date(2024, 12, 31)):
                    continue
            except ValueError:
                # 日期格式错误，跳过该行
                continue

            # 去除重复行（基于 name 和 value）
            if (row.get('name') is not None and row.get('value') is not None):
                key = (row['name'], str(row['value']).strip())
                if key in cleaned_rows:
                    continue

            # 清理空值：name 和 value 为空则跳过
            if not row.get('name'):
                continue

            # 格式化金额：去除千分位和货币符号，保留数字
            if value_str:
                clean_value = value_str.replace(',', '').replace('$', '').strip()
                cleaned_rows.append({
                    'date': date_obj.isoformat(),
                    'name': row['name'],
                    'value': clean_value
                })
            else:
                cleaned_rows.append({
                    'date': date_obj.isoformat(),
                    'name': row['name'],
                    'value': ''
                })
    return cleaned_rows

# 3. 主入口
if __name__ == '__main__':
    import sys
    csv_path = sys.argv[1] if len(sys.argv) > 1 else 'data.csv'
    rows = clean_data(csv_path)
    with open('output.csv', 'w', newline='', encoding='utf-8') as f:
        writer = csv.DictWriter(f, fieldnames=['date', 'name', 'value'])
        writer.writeheader()
        for row in rows:
            writer.writerow(row)

