"""把多行 JSON 日志按小时聚合成统计表，输出 CSV。"""
import json
from datetime import datetime, timedelta

def parse_json_logs(file_path):
    """读取并解析 JSON 格式日志文件。"""
    logs = []
    with open(file_path, 'r', encoding='utf-8') as f:
        for line in f:
            if line.strip():
                try:
                    log_entry = json.loads(line)
                    logs.append(log_entry)
                except json.JSONDecodeError:
                    continue
    return logs

def group_by_hour(logs):
    """按小时聚合日志条目。"""
    hour_counts = {}
    for log in logs:
        timestamp_str = log.get('timestamp', '')
        if not isinstance(timestamp_str, str):
            continue
        try:
            dt = datetime.fromisoformat(timestamp_str.replace('Z', '+00:00'))
        except (ValueError, AttributeError):
            continue
        hour_key = dt.strftime('%Y-%m-%d %H')
        if hour_key not in hour_counts:
            hour_counts[hour_key] = 0
        hour_counts[hour_key] += 1
    return hour_counts

def write_csv(hour_counts, output_path):
    """将聚合结果写入 CSV 文件。"""
    import csv
    with open(output_path, 'w', newline='', encoding='utf-8') as f:
        writer = csv.writer(f)
        writer.writerow(['hour', 'count'])
        for hour in sorted(hour_counts.keys()):
            writer.writerow([hour, hour_counts[hour]])

def main():
    """主入口：读取日志，聚合，按小时输出 CSV。"""
    input_file = 'logs.json'
    output_file = 'hourly_stats.csv'
    logs = parse_json_logs(input_file)
    hour_counts = group_by_hour(logs)
    write_csv(hour_counts, output_file)

if __name__ == '__main__':
    main()

"""日志聚合脚本：按天汇总各服务日志，输出到 stdout。"""
import sys
from datetime import datetime, timezone

# 日志格式：<timestamp> <service_name> <message>
def parse_line(line):
    """解析单行日志，返回 (timestamp, service, message)。"""
    parts = line.strip().split()
    if len(parts) != 3:
        return None
    try:
        ts_str = parts[0]
        # 处理时区：假设 timestamp 是 ISO8601 格式，包含 +00:00 或 -05:00 等偏移量
        dt = datetime.fromisoformat(ts_str)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
    except ValueError:
        return None
    return (dt, parts[1], parts[2])

# 按天聚合：key 为日期字符串 "YYYY-MM-DD"，value 为 dict {service: [list of messages]}
def aggregate_by_date(log_lines):
    """按天聚合日志。log_lines 是已解析的 (timestamp, service, message) 列表。"""
    result = {}
    for entry in log_lines:
        if entry is None:
            continue
        dt, service, message = entry
        date_key = dt.strftime("%Y-%m-%d")
        if date_key not in result:
            result[date_key] = {}
        # 追加消息到对应服务的列表中
        if service not in result[date_key]:
            result[date_key][service] = []
        result[date_key][service].append(message)
    return result

# 输出：按日期排序，逐个打印 "YYYY-MM-DD: {service} -> {messages}"
def print_aggregated(logs):
    """按日期顺序输出聚合结果。"""
    for date_key in sorted(logs.keys()):
        services = logs[date_key]
        for service, messages in services.items():
            # 格式化消息：用换行符分隔
            formatted_messages = "\n".join(messages)
            print(f"{date_key}: {service} -> {formatted_messages}")

# 主入口
if __name__ == "__main__":
    # 读取 stdin 中的日志行
    log_lines = []
    for line in sys.stdin:
        parsed = parse_line(line)
        if parsed is not None:
            log_lines.append(parsed)
    aggregated = aggregate_by_date(log_lines)
    print_aggregated(aggregated)

"""日志聚合脚本：按时间范围和关键词过滤日志并输出汇总。"""
import sys
from datetime import datetime, timezone


def parse_log_line(line):
    """解析单行日志，返回 (timestamp, level, message) 或 None。"""
    try:
        # 假设日志格式：2023-01-01T12:00:00Z INFO user login
        parts = line.strip().split(' ', 2)
        if len(parts) < 3:
            return None
        timestamp_str, level, message = parts[0], parts[1], ' '.join(parts[2:])
        # 解析时间戳（支持 ISO8601 和带时区的格式）
        try:
            if '+' in timestamp_str or '\Z' in timestamp_str:
                dt = datetime.fromisoformat(timestamp_str.replace('\Z', '+00:00'))
            else:
                dt = datetime.fromisoformat(timestamp_str)
        except ValueError:
            return None
        # 验证时间戳格式
        if not isinstance(dt, datetime):
            return None
        return (dt, level, message.strip())
    except Exception:
        return None


def filter_logs(logs, start_time, end_time, keywords):
    """过滤日志：按时间范围和关键词匹配。返回符合条件的日志列表。"""
    filtered = []
    for log in logs:
        if parse_log_line(log) is None:
            continue
        dt, level, message = parse_log_line(log)
        # 检查时间是否在范围内（包含边界）
        if start_time <= dt <= end_time:
            # 检查消息中是否包含任意关键词（不区分大小写）
            for keyword in keywords:
                if keyword.lower() in message.lower():
                    filtered.append(log)
                    break
    return filtered


def aggregate_logs(filtered_logs):
    """聚合日志：按级别统计数量并输出汇总。"""
    summary = {}
    for log in filtered_logs:
        dt, level, message = parse_log_line(log)
        if level not in summary:
            summary[level] = 0
        summary[level] += 1
    return summary


def main():
    """主入口：读取日志文件，过滤并输出汇总。"""
    # 默认参数，可通过命令行覆盖
    start_time = datetime.now(timezone.utc).replace(hour=0, minute=0, second=0)
    end_time = (datetime.now(timezone.utc) + __import__('datetime').timedelta(days=1)).replace(hour=23, minute=59, second=59)
    keywords = ['error', 'warning']

    # 读取日志文件
    try:
        with open(sys.argv[1] if len(sys.argv) > 1 else 'logs.txt', 'r') as f:
            logs = [line.rstrip('\n') for line in f]
    except FileNotFoundError:
        print(f"日志文件未找到: {sys.argv[1]}")
        sys.exit(1)

    # 过滤并聚合
    filtered = filter_logs(logs, start_time, end_time, keywords)
    summary = aggregate_logs(filtered)

    # 输出汇总
    print("日志汇总:")
    for level in sorted(summary.keys()):
        print(f"{level}: {summary[level]}")


if __name__ == '__main__':
    main()

