"""生成文档的脚本：路由带路径参数、嵌套路由、同名方法不同路径。"""
import os
from typing import List, Tuple, Dict

class DocGenerator:
    """文档生成器。"""
    def __init__(self):
        self.routes: List[Tuple[str, str]] = []
        self.metadata: Dict[str, str] = {}

    def add_route(self, path: str, method: str) -> None:
        """添加路由。"""
        if not path or not method:
            raise ValueError("路径和方法不能为空")
        self.routes.append((path, method))

    def add_metadata(self, key: str, value: str) -> None:
        """添加元数据。"""
        if not key or not value:
            raise ValueError("键和值不能为空")
        self.metadata[key] = value

    def generate_docs(self) -> List[str]:
        """生成文档列表。"""
        docs: List[str] = []
        for path, method in self.routes:
            if not path or not method:
                continue
            doc_line = f"- {method.upper()} {path}"
            docs.append(doc_line)
        return docs

    def get_metadata(self) -> Dict[str, str]:
        """获取元数据。"""
        return self.metadata.copy()


def main():
    generator = DocGenerator()
    generator.add_route("/api/v1/users", "GET")
    generator.add_route("/api/v1/users/<id>", "GET")
    generator.add_route("/api/v1/posts", "POST")
    generator.add_metadata("title", "API Documentation")
    docs = generator.generate_docs()
    print("\n".join(docs))

if __name__ == "__main__":
    main()

"""扫描目录下的重复文件（按内容哈希），支持 --dry-run 与 --json 输出。"""
import argparse
import hashlib
import os
import sys

def get_file_hash(filepath):
    """计算文件的 SHA256 哈希值。"""
    sha256 = hashlib.sha256()
    with open(filepath, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            sha256.update(chunk)
    return sha256.hexdigest()


def scan_directory(dir_path):
    """扫描目录，返回 {hash: [filepath]} 的字典。"""
    result = {}
    for root, _, files in os.walk(dir_path):
        for file in files:
            full_path = os.path.join(root, file)
            if not os.path.isfile(full_path):
                continue
            try:
                h = get_file_hash(full_path)
            except (OSError, IOError) as e:
                print(f"[error] {full_path}: {e}", file=sys.stderr)
                continue
            result.setdefault(h, []).append(full_path)
    return result


def find_duplicates(data):
    """从哈希字典中找出所有重复的文件。返回列表 [(hash, [paths])，其中 len>1]。”"""
    duplicates = []
    for h, paths in data.items():
        if len(paths) > 1:
            duplicates.append((h, paths))
    return duplicates


def format_output(data):
    """根据 --json 与 --dry-run 生成输出。"""
    dry_run = '--dry-run' in sys.argv or getattr(sys.argv[0], 'arg_dry_run', False)
    json_out = '--json' in sys.argv
    if not (dry_run or json_out):
        print("使用 --dry-run 或 --json 参数。")
        return
    for h, paths in data.items():
        if len(paths) > 1:
            print(f"{h}: {', '.join(paths)}")


def main(argv=None):
    """命令行入口。"""
    parser = argparse.ArgumentParser(description='扫描目录下的重复文件（按内容哈希）。')
    parser.add_argument('directory', help='要扫描的目录路径')
    parser.add_argument('--dry-run', action='store_true', help='不实际删除，仅显示结果。')
    parser.add_argument('--json', action='store_true', help='以 JSON 格式输出。')
    args = parser.parse_args(argv)

    data = scan_directory(args.directory)
    duplicates = find_duplicates(data)
    if json_out:
        print(json.dumps(duplicates, indent=2))
    elif dry_run:
        format_output(data)
    else:
        print("使用 --dry-run 或 --json 参数。")


if __name__ == '__main__':
    main()

"""大文件分块哈希工具：按大小分组后对同尺寸文件算哈希。"""
import os
from collections import defaultdict

def _group_by_size(path_list):
    groups = defaultdict(list)
    for p in path_list:
        if not os.path.isfile(p):
            continue
        sz = os.path.getsize(p)
        groups[sz].append(p)
    return groups

def _hash_file(path, chunk_size=65536):
    h = 0
    with open(path, 'rb') as f:
        while True:
            data = f.read(chunk_size)
            if not data:
                break
            for b in data:
                h ^= b
    return h

def _hash_group(groups):
    result = {}
    for sz, files in groups.items():
        hashes = set()
        for f in files:
            hashes.add(_hash_file(f))
        result[sz] = hashes
    return result

def main(path_list):
    groups = _group_by_size(path_list)
    return _hash_group(groups)

if __name__ == '__main__':
    import sys
    paths = [p for p in sys.argv[1:] if os.path.isfile(p)]
    print(_hash_file(paths[0]))

