import csv
from datetime import datetime, date

def parse_date(s):
    """尝试解析多种日期格式，返回 datetime 或 None。"""
    for fmt in ('%Y-%m-%d', '%Y/%m/%d', '%Y.%m.%d'):
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            continue
    return None

def load_data(path):
    """读取 CSV，返回 (rows, header) 列表。"""
    with open(path, newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        rows = [dict(r) for r in reader]
    return rows

def filter_by_date(rows, start, end):
    """按日期范围过滤行。"""
    result = []
    for row in rows:
        d = parse_date(row['date'])
        if d is None or not (start <= d <= end):
            continue
        result.append(row)
    return result

def remove_duplicates(rows):
    """按 date+amount 去重，保留首次出现。"""
    seen = set()
    out = []
    for row in rows:
        key = (row['date'], row['amount'])
        if key not in seen:
            seen.add(key)
            out.append(row)
    return out

def sort_by_amount(rows):
    """按金额降序排序。"""
    return sorted(rows, key=lambda r: float(r['amount']), reverse=True)

def main():
    path = input('请输入 CSV 文件路径：')
    rows = load_data(path)
    start = date.today() - timedelta(days=30)
    end = date.today() + timedelta(days=7)
    rows = filter_by_date(rows, start, end)
    rows = remove_duplicates(rows)
    rows = sort_by_amount(rows)
    with open('cleaned.csv', 'w', newline='', encoding='utf-8') as f:
        writer = csv.DictWriter(f, fieldnames=rows[0].keys())
        writer.writeheader()
        writer.writerows(rows)

if __name__ == '__main__':
    main()

"""实现一个线程安全的并发任务执行器。"""
import threading
from typing import List, Callable, Any

class ThreadSafeWorker:
    def __init__(self):
        self._lock = threading.Lock()
        self._results: List[Any] = []

    def execute(self, func: Callable[[], Any]) -> None:
        """执行任务并记录结果。"""
        with self._lock:
            result = func()
            self._results.append(result)

    def get_results(self) -> List[Any]:
        """获取所有已执行的结果。"""
        return list(self._results)

"""把多行 JSON 日志按小时聚合成统计表，输出 CSV。"""
import json
from datetime import datetime, timedelta

def parse_json_log(file_path):
    """解析 JSON 格式日志文件，每行一个对象。"""
    records = []
    with open(file_path, 'r', encoding='utf-8') as f:
        for line in f:
            if line.strip():
                try:
                    data = json.loads(line)
                    records.append(data)
                except json.JSONDecodeError:
                    continue
    return records

def group_by_hour(records):
    """按小时分组，返回字典 {小时: [记录]}。"""
    groups = {}
    for record in records:
        timestamp = record.get('timestamp')
        if not isinstance(timestamp, str):
            continue
        try:
            dt = datetime.fromisoformat(timestamp.replace('Z', '+00:00'))
        except ValueError:
            continue
        hour_key = dt.strftime('%Y-%m-%d %H')
        groups.setdefault(hour_key, []).append(record)
    return groups

def write_csv(groups):
    """将分组结果写入 CSV。"""
    import csv
    with open('hourly_stats.csv', 'w', newline='', encoding='utf-8') as f:
        writer = csv.writer(f)
        writer.writerow(['小时', '记录数'])
        for hour_key, records in groups.items():
            writer.writerow([hour_key, len(records)])

if __name__ == '__main__':
    import sys
    file_path = sys.argv[1] if len(sys.argv) > 1 else 'logs.json'
    records = parse_json_log(file_path)
    groups = group_by_hour(records)
    write_csv(groups)

"""日志聚合脚本：处理多源日志并输出汇总报告。"""
import os
import sys
from datetime import datetime

# 数据结构定义
class LogEntry:
    def __init__(self, source: str, level: str, message: str):
        self.source = source  # 日志来源，如 'app.log'
        self.level = level     # 日志级别：INFO、WARN、ERROR
        self.message = message # 日志内容

# 核心函数：解析日志行并过滤无效数据
def parse_log_line(line: str) -> LogEntry | None:
    """解析单行日志，返回 LogEntry 或 None。"""
    line = line.strip()
    if not line or '{' in line:
        return None
    try:
        parts = line.split(' ', 2)
        source, level, message = parts[0], parts[1], ' '.join(parts[2:])
        return LogEntry(source=source, level=level, message=message)
    except (IndexError, ValueError):
        return None

# 核心函数：聚合多源日志并生成报告
def aggregate_logs(log_lines: list) -> dict:
    """聚合日志行，返回汇总字典。"""
    report = {'total': 0, 'by_source': {}, 'by_level': {}}
    for line in log_lines:
        entry = parse_log_line(line)
        if not entry:
            continue
        report['total'] += 1
        report['by_source'][entry.source] = report['by_source'].get(entry.source, 0) + 1
        report['by_level'][entry.level] = report['by_level'].get(entry.level, 0) + 1
    return report

# 主入口：读取文件并输出报告
def main():
    """主函数：读取日志文件，解析并输出汇总。"""
    if len(sys.argv) < 2:
        print("用法: python log_aggregator.py <log_file>")
        sys.exit(1)
    file_path = sys.argv[1]
    with open(file_path, 'r', encoding='utf-8') as f:
        lines = f.readlines()
    report = aggregate_logs(lines)
    print(f"总日志数: {report['total']}")
    for source, count in report['by_source'].items():
        print(f"来源 {source}: {count} 条")
    for level, count in report['by_level'].items():
        print(f"级别 {level}: {count} 条")

if __name__ == "__main__":
    main()

