"""扫描目录下重复文件（按内容哈希），支持 --dry-run 与 --json 输出。"""
import argparse
import hashlib
import os
from pathlib import Path


def compute_hash(filepath):
    """计算文件的 MD5 哈希值。"""
    h = hashlib.md5()
    with open(filepath, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            h.update(chunk)
    return h.hexdigest()


def find_duplicates(root_dir):
    """返回 (hash, list_of_files) 的字典。"""
    root = Path(root_dir).resolve()
    files_by_hash = {}
    for path in root.rglob('*'):
        if path.is_file():
            h = compute_hash(path)
            files_by_hash.setdefault(h, []).append(str(path))
    return files_by_hash


def main():
    parser = argparse.ArgumentParser(description='扫描目录下重复文件（按内容哈希）。')
    parser.add_argument('directory', help='要扫描的根目录。')
    parser.add_argument('--dry-run', action='store_true', help='不实际删除，仅列出重复项。')
    parser.add_argument('--json', action='store_true', help='以 JSON 格式输出。')
    args = parser.parse_args()

    result = find_duplicates(args.directory)
    for h, files in result.items():
        if len(files) > 1:
            print(json.dumps({'hash': h, 'files': files}))

if __name__ == '__main__':
    main()

"""测试工具：验证目录是否存在、是否为空、是否同名不同内容、以及是否存在真重复（文件级）。"""
import os
from typing import List, Tuple, Optional

class DirectoryChecker:
    def __init__(self):
        self.errors: List[Tuple[str, str]] = []

    def check_dir_exists(self, path: str) -> bool:
        """检查目录是否存在。"""
        return os.path.isdir(path)

    def check_is_empty(self, path: str) -> bool:
        """检查目录是否为空（无文件、无子目录）。"""
        if not self.check_dir_exists(path):
            return False
        for entry in os.listdir(path):
            full_path = os.path.join(path, entry)
            if os.path.isdir(full_path) or os.path.isfile(full_path):
                return False
        return True

    def check_same_name_different_content(self, dir1: str, dir2: str) -> bool:
        """检查两个目录是否同名但内容不同。"""
        if not self.check_dir_exists(dir1):
            return False
        if not self.check_dir_exists(dir2):
            return False
        if dir1 != dir2:
            return True
        files1 = set(os.listdir(dir1))
        files2 = set(os.listdir(dir2))
        return files1 != files2

    def check_true_duplicate(self, path: str) -> bool:
        """检查目录中是否存在真重复文件（同一内容，多个文件）。"""
        if not self.check_dir_exists(path):
            return False
        seen = {}
        for entry in os.listdir(path):
            full_path = os.path.join(path, entry)
            if os.path.isfile(full_path):
                with open(full_path, 'rb') as f:
                    content = f.read()
                seen[content] = seen.get(content, 0) + 1
        return any(count > 1 for count in seen.values())

    def run_check(self, paths: List[str]) -> Tuple[bool, List[Tuple[str, str]]]:
        """运行所有检查，返回是否通过及错误列表。"""
        errors = []
        for path in paths:
            if not self.check_dir_exists(path):
                errors.append((path, '目录不存在'))
            elif not self.check_is_empty(path):
                errors.append((path, '目录不为空'))
            else:
                # 检查同名不同内容（需要两个路径，这里简化处理）
                pass
        return len(errors) == 0, errors

if __name__ == "__main__":
    checker = DirectoryChecker()
    paths = ["/tmp", "/nonexistent", ".", "./test.py"]
    passed, errors = checker.run_check(paths)
    print(f"通过: {passed}")
    for error in errors:
        print(f"错误: {error}")

"""清洗 CSV 数据：处理缺失值、重复行与日期格式混乱。"""
import csv
from datetime import datetime

def load_csv(path):
    """读取 CSV，返回列表（每行是字符串列表）。"""
    rows = []
    with open(path, newline='', encoding='utf-8') as f:
        reader = csv.reader(f)
        for row in reader:
            rows.append(row)
    return rows

def clean_rows(rows):
    """删除完全重复的行。"""
    seen = set()
    cleaned = []
    for row in rows:
        key = tuple(row)
        if key not in seen:
            seen.add(key)
            cleaned.append(row)
    return cleaned

def fix_date(date_str):
    """尝试将字符串转为日期，失败返回原值。"""
    for fmt in ('%Y-%m-%d', '%Y/%m/%d', '%d-%m-%Y'):
        try:
            return datetime.strptime(date_str, fmt).strftime('%Y-%m-%d')
        except ValueError:
            continue
    return date_str

def clean_data(rows):
    """处理缺失值与日期格式。"""
    cleaned = []
    for row in rows:
        new_row = []
        for cell in row:
            if cell == '':
                continue  # 跳过空单元格
            try:
                new_cell = float(cell)
            except ValueError:
                new_cell = int(cell) if '.' not in cell else cell
            new_row.append(new_cell)
        cleaned.append(new_row)
    return cleaned

def save_csv(path, rows):
    """写入规范 CSV。"""
    with open(path, 'w', newline='', encoding='utf-8') as f:
        writer = csv.writer(f)
        for row in rows:
            writer.writerow(row)

if __name__ == '__main__':
    import sys
    input_path = sys.argv[1] if len(sys.argv) > 1 else 'input.csv'
    output_path = sys.argv[2] if len(sys.argv) > 2 else 'output.csv'
    rows = load_csv(input_path)
    rows = clean_rows(rows)
    rows = clean_data(rows)
    save_csv(output_path, rows)

"""清洗脚本：读取 CSV、按日期范围过滤、去除重复行、处理金额格式。"""
import csv
from datetime import datetime

def parse_date(date_str):
    """解析日期字符串，支持多种格式。"""
    for fmt in ("%Y-%m-%d", "%Y/%m/%d", "%d-%m-%Y", "%d/%m/%Y"):
        try:
            return datetime.strptime(date_str, fmt)
        except ValueError:
            continue
    raise ValueError(f"无法解析日期：{date_str}")

def clean_amount(amount_str):
    """清洗金额字符串，去除千分位和货币符号。"""
    if not amount_str or amount_str.strip() == "":
        return ""
    cleaned = amount_str.replace("$", "").replace("¥", "")
    cleaned = cleaned.replace("\u00a5", "")  # 欧元符号
    if "K" in cleaned or "k" in cleaned:
        return cleaned.replace("K", "").replace("k", "")
    try:
        return f"{float(cleaned):,.2f}"
    except ValueError:
        return cleaned

def load_data(filepath):
    """读取 CSV 文件，返回行数据列表。"""
    rows = []
    with open(filepath, newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        for row in reader:
            rows.append(row)
    return rows

def filter_by_date(rows, start_date, end_date):
    """按日期范围过滤行。"""
    filtered = []
    for row in rows:
        try:
            date_val = parse_date(row.get("date", ""))
            if start_date <= date_val <= end_date:
                filtered.append(row)
        except ValueError:
            continue
    return filtered

def remove_duplicates(rows):
    """去除重复行（基于所有字段）。"""
    seen = set()
    unique_rows = []
    for row in rows:
        key = tuple(row.values())
        if key not in seen:
            seen.add(key)
            unique_rows.append(row)
    return unique_rows

def clean_amounts(rows):
    """清洗所有金额字段。"""
    for row in rows:
        if "amount" in row:
            row["amount"] = clean_amount(row.get("amount", ""))
    return rows

def main():
    import sys
    filepath = sys.argv[1] if len(sys.argv) > 1 else "data.csv"
    start_date = parse_date("2023-01-01")
    end_date = parse_date("2024-12-31")
    rows = load_data(filepath)
    rows = filter_by_date(rows, start_date, end_date)
    rows = remove_duplicates(rows)
    rows = clean_amounts(rows)
    with open("output.csv", "w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=rows[0].keys()) if rows else None
        writer.writeheader()
        for row in rows:
            writer.writerow(row)

if __name__ == "__main__":
    main()

