"""日志聚合脚本：按时间窗口将多源日志写入本地文件。"""
import os
from datetime import datetime, timezone

# 日志格式：timestamp|level|message
LOG_FORMAT = "%Y-%m-%d %H:%M:%S | %-15s | %s"


def parse_line(line):
    """解析单行日志，返回 (ts, level, message)。"""
    parts = line.split("|")
    if len(parts) != 3:
        return None
    ts_str, level, msg = parts
    try:
        dt = datetime.strptime(ts_str.strip(), "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
    except ValueError:
        return None
    return (dt, level.strip(), msg.strip())


def read_logs(path):
    """读取日志文件，返回 [(ts, level, message), ...] 列表。"""
    result = []
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            parsed = parse_line(line)
            if parsed is None:
                continue
            result.append(parsed)
    return result


def write_window(logs, path):
    """按时间窗口将日志写入文件。"""
    if not logs:
        return
    # 按时间排序
    sorted_logs = sorted(logs, key=lambda x: x[0])
    out_path = path + ".agg"
    with open(out_path, "w", encoding="utf-8") as f:
        for i in range(0, len(sorted_logs), 10):
            chunk = sorted_logs[i:i+10]
            f.write("\n".join([LOG_FORMAT % (ts, level, msg) for ts, level, msg in chunk]))
            if i + 10 < len(sorted_logs):
                f.write("\n---")


def main():
    """入口：读取日志并写入聚合文件。"""
    import sys
    log_path = sys.argv[1] if len(sys.argv) > 1 else ".logs"
    write_window(read_logs(log_path), log_path)


if __name__ == "__main__":
    main()

"""日志聚合脚本：按时间、级别和文件名对日志行进行分组与统计。"""
import os
import sys
from collections import defaultdict

# 定义日志结构：每行包含 [timestamp, level, message] 三部分。
LOG_STRUCTURE = "[timestamp, level, message]"

class LogAggregator:
    """聚合日志数据并返回统计信息。"""

    def __init__(self):
        # 存储按 (time, level, filename) 分组的日志行列表
        self._groups = defaultdict(list)

    def add_log(self, timestamp, level, message, filename):
        """将一条日志加入对应分组。"""
        key = (timestamp, level, filename)
        self._groups[key].append(message)

    def get_stats(self):
        """返回各分组的统计信息：行数、最大长度和最小时间戳。"""
        stats = {}
        for key, messages in self._groups.items():
            # 提取分组中的所有日志消息
            all_messages = [msg for msg in messages]
            max_len = max(len(msg) for msg in all_messages)
            min_time = min(key[0])
            stats[key] = {
                "count": len(all_messages),
                "max_length": max_len,
                "min_timestamp": min_time
            }
        return stats

    def get_logs(self, key):
        """返回指定分组的日志消息列表。"""
        if key in self._groups:
            return list(self._groups[key])
        else:
            return []

if __name__ == "__main__":
    # 示例用法：读取文件并聚合日志
    input_file = sys.argv[1] if len(sys.argv) > 1 else "input.log"
    output_file = sys.argv[2] if len(sys.argv) > 2 else "output.json"

    aggregator = LogAggregator()
    with open(input_file, "r", encoding="utf-8") as f:
        for line in f:
            # 解析日志行：提取时间戳、级别和消息内容
            parts = line.strip().split(", ")
            if len(parts) == 3:
                timestamp, level, message = parts[0], parts[1], ""
                for part in parts[2].split("\n"):
                    message += part + "\n"
                aggregator.add_log(timestamp.strip(), level.strip(), message, os.path.basename(input_file))

    stats = aggregator.get_stats()
    with open(output_file, "w", encoding="utf-8") as f:
        import json
        json.dump(stats, f, indent=2)

