"""扫描目录下的重复文件（按内容哈希），支持 --dry-run 与 --json 输出。"""
import argparse
import hashlib
import os
import sys

def compute_hash(filepath):
    """计算文件的 SHA-256 哈希值。"""
    h = hashlib.sha256()
    with open(filepath, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            h.update(chunk)
    return h.hexdigest()


def find_duplicates(root_dir):
    """返回 (hash, list_of_files) 的字典。"""
    hash_map = {}
    for dirpath, _, filenames in os.walk(root_dir):
        for filename in filenames:
            filepath = os.path.join(dirpath, filename)
            if not os.path.isfile(filepath):
                continue
            try:
                h = compute_hash(filepath)
            except Exception as e:
                print(f"Error hashing {filepath}: {e}", file=sys.stderr)
                continue
            hash_map.setdefault(h, []).append(filepath)
    return hash_map


def main():
    parser = argparse.ArgumentParser(description='Find duplicate files by content.')
    parser.add_argument('directory', help='Directory to scan')
    parser.add_argument('--dry-run', action='store_true', help='Show what would be found without removing')
    parser.add_argument('--json', action='store_true', help='Output in JSON format')
    args = parser.parse_args()

    if not os.path.isdir(args.directory):
        print(f"Error: {args.directory} is not a valid directory.", file=sys.stderr)
        sys.exit(1)

    result = find_duplicates(args.directory)
    duplicates = [(h, files) for h, files in result.items() if len(files) > 1]

    if args.json:
        import json
        print(json.dumps([{'hash': h, 'files': f} for h, f in duplicates], indent=2))
    else:
        for h, files in duplicates:
            print(f"Hash: {h}")
            for filepath in sorted(files):
                print(filepath)


if __name__ == '__main__':
    main()

"""测试工具：验证目录是否存在、是否为空、同名不同内容、存在真重复四种情况。"""
def check_dir_exists(path):
    return os.path.exists(path)
def is_empty_dir(path):
    if not os.path.isdir(path):
        return False
    try:
        entries = os.listdir(path)
    except FileNotFoundError:
        return False
    return len(entries) == 0
def check_same_name_different_content(dir1, dir2):
    if not (os.path.isdir(dir1) and os.path.isdir(dir2)):
        return False
    try:
        entries = os.listdir(dir1)
    except FileNotFoundError:
        return False
    for entry in entries:
        path1 = os.path.join(dir1, entry)
        path2 = os.path.join(dir2, entry)
        if not (os.path.isfile(path1) and os.path.isfile(path2)):
            continue
        with open(path1, 'rb') as f1:
            content1 = f1.read()
        with open(path2, 'rb') as f2:
            content2 = f2.read()
        if content1 != content2:
            return True
    return False
def check_true_duplicate(dir_path):
    seen = {}
    try:
        entries = os.listdir(dir_path)
    except FileNotFoundError:
        return False
    for entry in entries:
        path = os.path.join(dir_path, entry)
        if not os.path.isfile(path):
            continue
        with open(path, 'rb') as f:
            content = f.read()
        key = (entry, content[:16])  # 用前 16 个字节作为哈希键
        if key in seen:
            return True
        seen[key] = entry
    return False
if __name__ == "__main__":
