    print("目录存在：", check_dir_exists("/tmp"))
    print("空目录：", is_empty_dir(os.path.join(os.getcwd(), 'test_empty')))
    print("同名不同内容：", check_same_name_different_content("/tmp", os.path.join(os.getcwd(), 'test1')))
    print("真重复：", check_true_duplicate(os.path.join(os.getcwd(), 'test2')))

"""大文件哈希优化器：按大小分组后只对同尺寸文件算哈希，避免全量读取大文件。"""
import os
from collections import defaultdict

def group_by_size(file_paths):
    """按文件大小分组，返回 dict: {size_bytes: [paths]}."""
    groups = defaultdict(list)
    for path in file_paths:
        try:
            size = os.path.getsize(path)
        except OSError:
            continue
        groups[size].append(path)
    return dict(groups)


def hash_file(path):
    """计算单个文件的 SHA-256 哈希。"""
    import hashlib
    h = hashlib.sha256()
    with open(path, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            h.update(chunk)
    return h.hexdigest()


def process_grouped(file_paths):
    """对每个大小组独立计算哈希，避免大文件阻塞。"""
    result = {}
    for size, paths in file_paths.items():
        if len(paths) == 1:
            # 单文件直接算哈希
            try:
                result[paths[0]] = hash_file(paths[0])
            except OSError as e:
                result[paths[0]] = f"error: {e}"
        else:
            # 多文件组：先统计总大小，再对每个文件算哈希
            total_size = sum(os.path.getsize(p) for p in paths)
            hashes = []
            for path in paths:
                try:
                    hashes.append(hash_file(path))
                except OSError as e:
                    hashes.append(f"error: {e}")
            result[paths] = f"total_size={total_size}, count={len(hashes)}"
    return result


def main():
    """入口：读取目录下所有 .txt 文件，按大小分组后计算哈希。"""
    import sys
    root_dir = sys.argv[1] if len(sys.argv) > 1 else '.'
    txt_files = [os.path.join(root_dir, f) for f in os.listdir(root_dir)
                 if f.endswith('.txt')]
    print("分组前文件数:", len(txt_files))
    grouped = group_by_size(txt_files)
    print("分组后组数:", len(grouped))
    result = process_grouped(txt_files)
    for path, value in result.items():
        print(f"{path}: {value}")


if __name__ == '__main__':
    main()

"""清洗脚本：读取 CSV、按日期范围过滤、去除重复行、清理金额字段。"""
import csv
from datetime import datetime, timedelta

# ---------- 数据结构 ----------
def _parse_date(s):
    """尝试解析多种日期格式，返回 datetime 或 None。"""
    for fmt in ("%Y-%m-%d", "%Y/%m/%d", "%d-%m-%Y", "%d/%m/%Y"):
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            continue
    return None

# ---------- 核心函数 ----------
def filter_by_date_range(file_path: str, start: datetime, end: datetime) -> list[dict]:
    """读取 CSV，按日期范围过滤行。返回清洗后的列表。"""
    rows = []
    with open(file_path, newline="", encoding="utf-8-sig") as f:
        reader = csv.DictReader(f)
        for row in reader:
            d = _parse_date(row.get("date", ""))
            if d is None or not (start <= d <= end):
                continue
            rows.append(row)
    return rows


def dedupe(rows: list[dict]) -> list[dict]:
    """去重：按 date+amount 组合。"""
    seen = set()
    result = []
    for row in rows:
        key = (row.get("date", ""), row.get("amount", ""))
        if key not in seen:
            seen.add(key)
            result.append(row)
    return result


def clean_amount(rows: list[dict]) -> list[dict]:
    """清理金额：去除千分位和货币符号。"""
    for row in rows:
        raw = row.get("amount", "")
        cleaned = raw.replace(",", "").replace("$", "").strip()
        row["amount"] = cleaned
    return rows


def main(file_path: str, start: datetime, end: datetime) -> None:
    """入口：读取、过滤、去重、清理金额。"""
    raw = filter_by_date(file_path, start, end)
    deduped = dedupe(raw)
    cleaned = clean_amount(deduped)
    with open("output.csv", "w", newline="", encoding="utf-8-sig") as f:
        writer = csv.DictWriter(f, fieldnames=list(cleaned[0].keys()) if cleaned else ["date", "amount"])
        writer.writeheader()
        for row in cleaned:
            writer.writerow(row)


if __name__ == "__main__":
    import sys
    start = datetime.strptime(sys.argv[1], "%Y-%m-%d")
    end = datetime.strptime(sys.argv[2], "%Y-%m-%d")
    main("input.csv", start, end)

"""清洗脚本：读取 UTF-8 文件，处理 BOM、编码错误和空值。"""
import os
import sys
from pathlib import Path

# 定义数据结构
class Data:
    def __init__(self, name):
        self.name = name

# 核心函数：读取并清洗文件

def clean_file(file_path: str) -> list:
    """读取指定路径的文本文件，返回清洗后的行列表。"""
    cleaned_lines = []
    try:
        with open(file_path, 'r', encoding='utf-8-sig') as f:
            for line in f:
                stripped_line = line.strip()
                if stripped_line:  # 跳过空行
                    cleaned_lines.append(stripped_line)
    except UnicodeDecodeError:
        print(f"编码错误：{file_path}，尝试使用 latin-1 解码。")
        try:
            with open(file_path, 'r', encoding='latin-1') as f:
                for line in f:
                    stripped_line = line.strip()
                    if stripped_line:
                        cleaned_lines.append(stripped_line)
        except Exception as e:
            print(f"读取失败：{e}")
    return cleaned_lines

"""任务清单管理器：增删改查 + HTTP 服务"""
import http.server
import socketserver
from typing import List, Dict

# ---------- 数据结构 ----------
def get_task_list() -> List[Dict[str, str]]:
    """返回当前所有任务清单。"""
    return []

def add_task(task: Dict[str, str]) -> bool:
    """添加任务：校验必填字段，追加到列表。"""
    required = ['id', 'name']
    if not all(k in task for k in required):
        return False
    get_task_list().append(task)
    return True

def update_task(id: str, new_data: Dict[str, str]) -> bool:
    """更新任务：按 id 查找，替换字段。"""
    tasks = get_task_list()
    for t in tasks:
        if t['id'] == id:
            t.update(new_data)
            return True
    return False

def delete_task(id: str) -> bool:
    """删除任务：按 id 查找并移除。"""
    tasks = get_task_list()
    tasks[:] = [t for t in tasks if t['id'] != id]
    return True

def list_tasks() -> List[Dict[str, str]]:
    """返回所有任务清单。"""
    return get_task_list()

# ---------- HTTP 服务 ----------
class TaskHandler(http.server.BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path == '/tasks':
            tasks = list_tasks()
            body = ''.join(json.dumps(t) for t in tasks)
            self.send_response(200)
            self.send_header('Content-Type', 'application/json')
            self.end_headers()
            self.wfile.write(body.encode())
        else:
            self.send_error(404, "Not Found")

    def do_POST(self):
        if self.path == '/tasks':
            content_length = int(self.headers.get('Content-Length', 0))
            raw_body = self.rfile.read(content_length)
            try:
                import json
                data = json.loads(raw_body.decode())
                add_task(data)
                self.send_response(200)
                self.end_headers()
            except Exception as e:
                self.send_error(400, str(e))
        else:
            self.send_error(404, "Not Found")

if __name__ == '__main__':
    with socketserver.TCPServer(('', 8080), TaskHandler) as httpd:
        print("Server running on http://localhost:8080/tasks")
        httpd.serve_forever()

