"""日志聚合脚本：按时间范围和字段过滤，将多源日志写入 JSONL。"""
import json
from datetime import datetime, timezone

# 时区转换工具：把 naive datetime 转为 UTC。
def to_utc(dt: datetime) -> datetime:
    """将 naive datetime 转为 UTC。"""
    if dt.tzinfo is None:
        return dt.replace(tzinfo=timezone.utc)
    return dt.astimezone(timezone.utc)

# 数据结构：每条日志记录。
def log_record(level: str, timestamp: datetime, message: str) -> dict:
    """构造一条日志记录的字典。"""
    return {
        "level": level,
        "timestamp": to_utc(timestamp),
        "message": message
    }

# 核心函数：过滤并写入日志。
def aggregate_logs(logs: list[dict], start_time: datetime, end_time: datetime) -> None:
    """按时间范围过滤日志，并逐行写入 JSONL。"""
    filtered = []
    for rec in logs:
        ts = to_utc(rec["timestamp"])
        if start_time <= ts <= end_time:
            filtered.append(log_record(
                level=rec["level"],
                timestamp=ts,
                message=rec["message"]
            ))
    with open("output.jsonl", "w", encoding="utf-8") as f:
        for rec in filtered:
            line = json.dumps(rec, ensure_ascii=False) + "\n"
            f.write(line)

"""日志聚合脚本：按时间、级别和来源过滤并输出汇总统计。"""
import sys
from datetime import datetime

def parse_line(line):
    """解析单行日志，返回 (timestamp, level, source) 或 None。"""
    parts = line.split('|')
    if len(parts) != 3:
        return None
    try:
        ts_str = parts[0].strip()
        lvl_str = parts[1].strip().lower()
        src_str = parts[2].strip()
        # 尝试解析时间戳，格式如 '2024-01-01T12:00:00Z'
        dt = datetime.fromisoformat(ts_str.replace('Z', '+00:00'))
    except Exception:
        return None
    if lvl_str not in ('info','warn','error'):
        return None
    return (dt, lvl_str, src_str)

def filter_lines(lines):
    """过滤出指定时间段、级别和来源的日志行。"""
    if not lines:
        return []
    # 取第一条作为起始，末条作为结束
    start = datetime.fromisoformat(lines[0].split('|')[0].strip().replace('Z', '+00:00'))
    end = datetime.fromisoformat(lines[-1].split('|')[0].strip().replace('Z', '+00:00'))
    filtered = []
    for line in lines:
        parsed = parse_line(line)
        if not parsed:
            continue
        dt, lvl, src = parsed
        if start <= dt <= end and lvl == 'error' and src == 'api':
            filtered.append(line)
    return filtered

def aggregate(filtered_lines):
    """对过滤后的日志行进行统计，返回字典。"""
    stats = {'total': 0, 'errors': 0}
    for line in filtered_lines:
        stats['total'] += 1
        if parse_line(line)[1] == 'error':
            stats['errors'] += 1
    return stats

def main():
    """主入口：读取日志文件，过滤并输出统计。"""
    filename = sys.argv[1] if len(sys.argv) > 1 else 'logs.txt'
    with open(filename, 'r', encoding='utf-8') as f:
        lines = [l.rstrip('\n') for l in f]
    filtered = filter_lines(lines)
    stats = aggregate(filtered)
    print(f"Total: {stats['total']}, Errors: {stats['errors']}")

if __name__ == '__main__':
    main()

