"""扫描目录下重复文件（按内容哈希），支持 --dry-run 与 --json 输出。"""
import argparse
import hashlib
import os
import sys
from pathlib import Path


def get_file_hash(filepath: str) -> str:
    """计算文件的 SHA256 哈希值。"""
    h = hashlib.sha256()
    with open(filepath, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            h.update(chunk)
    return h.hexdigest()


def find_duplicates(root_dir: str) -> list[tuple[str, str]]:
    """返回 (小文件路径, 大文件路径) 列表，按哈希分组。"""
    hash_map = {}
    for path in Path(root_dir).rglob('*'):
        if path.is_file():
            h = get_file_hash(str(path))
            if h not in hash_map:
                hash_map[h] = [str(path)]
            else:
                hash_map[h].append(str(path))
    result = []
    for paths in hash_map.values():
        if len(paths) > 1:
            # 按路径字典序排序，保证输出稳定
            paths_sorted = sorted(paths)
            result.append((paths_sorted[0], paths_sorted[-1]))
    return result


def main() -> None:
    parser = argparse.ArgumentParser(
        description='扫描目录下重复文件（按内容哈希），支持 --dry-run 与 --json 输出。')
    parser.add_argument('directory', help='要扫描的目录路径')
    parser.add_argument('--dry-run', action='store_true', help='不实际删除，仅显示将要操作的文件')
    parser.add_argument('--json', action='store_true', help='以 JSON 格式输出结果')
    args = parser.parse_args()

    if not os.path.isdir(args.directory):
        print(f'错误：目录 {args.directory} 不存在。', file=sys.stderr)
        sys.exit(1)

    duplicates = find_duplicates(args.directory)
    if args.json:
        import json
        print(json.dumps([{'small': a, 'large': b} for a, b in duplicates], indent=2))
    else:
        for small, large in duplicates:
            print(f'重复文件：{small} == {large}')


if __name__ == '__main__':
    main()

"""优化大文件哈希计算：先按文件大小分组，再对同尺寸文件算哈希，避免全量读取。"""
import os
from collections import defaultdict

def hash_file(path):
    """计算单个文件的 MD5 哈希。"""
    import hashlib
    h = hashlib.md5()
    with open(path, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            h.update(chunk)
    return h.hexdigest(), len(os.path.getsize(path))

def group_by_size(file_paths):
    """按文件大小分组，返回 {尺寸: [路径]}。"""
    groups = defaultdict(list)
    for p in file_paths:
        size = os.path.getsize(p) if os.path.exists(p) else 0
        groups[size].append(p)
    return dict(groups)

def hash_group(group):
    """对一组同尺寸文件算哈希，返回 {路径: (hash, 尺寸)}。"""
    result = {}
    for p in group:
        h, size = hash_file(p)
        result[p] = (h, size)
    return result

def main():
    """入口：从当前目录读取所有 .txt 文件，按大小分组后计算哈希。"""
    import sys
    paths = [os.path.join(dirname(__file__), f) for dirname in os.getcwd().split(os.sep) if dirname]
    txt_files = [p for p in paths if p.endswith('.txt')]
    groups = group_by_size(txt_files)
    all_hashes = {}
    for size, files in groups.items():
        print(f"处理尺寸 {size} GB 的文件：{len(files)} 个", file=sys.stderr)
        all_hashes.update(hash_group(files))
    import json
    print(json.dumps(all_hashes, indent=2, ensure_ascii=False))

