"""清洗 CSV 数据：处理缺失值、重复行与日期格式混乱问题。"""
import csv
from datetime import datetime, date

def is_valid_date(s):
    try:
        return bool(datetime.strptime(s.strip(), "%Y-%m-%d"))
    except ValueError:
        return False

def clean_csv(input_path, output_path):
    with open(input_path, "r", newline="") as infile, open(output_path, "w", newline="") as outfile:
        reader = csv.DictReader(infile)
        writer = csv.DictWriter(outfile, fieldnames=reader.fieldnames)
        writer.writeheader()

        seen = set()
        for row in reader:
            # 处理缺失值：用空字符串填充
            cleaned_row = {}
            for key, value in row.items():
                if value is None or value.strip() == "":
                    cleaned_row[key] = ""
                else:
                    cleaned_row[key] = value.strip()

            # 去重：基于所有字段组合
            row_key = tuple(cleaned_row.values())
            if row_key in seen:
                continue
            seen.add(row_key)

            # 日期清洗：若为字符串且格式混乱，尝试修正
            for key, value in cleaned_row.items():
                if is_valid_date(value):
                    continue
                try:
                    parsed = datetime.strptime(value.strip(), "%Y-%m-%d")
                    cleaned_row[key] = parsed.strftime("%Y-%m-%d")
                except ValueError:
                    pass  # 保留原始值

            writer.writerow(cleaned_row)

if __name__ == "__main__":
    import sys
    input_path = sys.argv[1] if len(sys.argv) > 1 else "input.csv"
    output_path = sys.argv[2] if len(sys.argv) > 2 else "output.csv"
    clean_csv(input_path, output_path)

"""清洗脚本：读取 UTF-8 文件，去除 BOM、首尾空白、空行，并输出清洗后的内容。"""
import os

# 定义文件路径（相对于当前工作目录）
FILES = [
    "data/clean_data.txt",
]


def read_file(path):
    """读取 UTF-8 文件，处理 BOM 和首尾空白。"""
    with open(path, 'r', encoding='utf-8') as f:
        content = f.read()
    return content.strip()


def clean_content(content):
    """清洗内容：去除空行和首尾空白。"""
    lines = [line for line in content.split('\n') if line.strip()]
    return '\n'.join(lines)


def main():
    """主函数：遍历 FILES，读取并清洗文件内容。"""
    for path in FILES:
        if os.path.exists(path):
            content = read_file(path)
            cleaned = clean_content(content)
            print(f"{path}: {cleaned}")


if __name__ == "__main__":
    main()

"""实现一个可并发工作的多线程任务执行器。"""
import threading
from typing import List, Callable, Any

class TaskQueue:
    def __init__(self):
        self._tasks: List[Callable] = []
        self._lock = threading.Lock()
        self._stop_event = threading.Event()

    def add_task(self, task: Callable) -> None:
        with self._lock:
            self._tasks.append(task)

    def get_next_task(self) -> Callable:
        with self._lock:
            if not self._tasks:
                return None
            return self._tasks.pop(0)

class Worker:
    def __init__(self, queue: TaskQueue):
        self.queue = queue
        self.thread = threading.Thread(target=self._run)

    def _run(self) -> None:
        while True:
            task = self.queue.get_next_task()
            if task is None:
                break
            try:
                result = task()
                print(f"Result: {result}")
            except Exception as e:
                print(f"Error: {e}")

    def join(self) -> None:
        self.thread.join()

if __name__ == "__main__":
    queue = TaskQueue()
    for i in range(5):
        queue.add_task(lambda x=i: print(f"Task {x}"))
    worker = Worker(queue)
    worker.join()

"""日志聚合脚本：按时间窗口将多台服务器的日志写入本地文件。"""
import os
from datetime import datetime, timezone

# 日志字段定义：每条记录的键名与类型
LOG_FIELDS = {
    "timestamp": str,
    "host": str,
    "level": str,
    "message": str,
}


def parse_line(line: str) -> dict:
    """解析单行日志，返回字段字典。跳过空行和以 # 开头的注释行。"""
    line = line.strip()
    if not line or line.startswith("#"):
        return None
    parts = line.split(None, 3)
    result = {}
    for key, value in zip(LOG_FIELDS.keys(), parts):
        if len(value) > 0:
            result[key] = value
    return result


def write_log(log_dir: str, log_file: str, records: list[dict]):
    """将记录写入文件，每行一条。"""
    os.makedirs(os.path.dirname(log_dir), exist_ok=True)
    with open(log_file, "w", encoding="utf-8") as f:
        for record in records:
            line = f"{record['timestamp']} {record['host']} {record['level']} {record['message']}\n"
            f.write(line)


def main():
    """入口：读取 stdin 日志，聚合后写入本地文件。"""
    records = []
    for line in sys.stdin:
        parsed = parse_line(line)
        if parsed is not None:
            records.append(parsed)
    write_log("/tmp/logs", "logs.txt", records)


if __name__ == "__main__":
    main()

"""日志聚合脚本：按时间、级别和来源过滤并输出汇总统计。"""
import sys
from datetime import datetime, timezone

# ---------- 数据结构 ----------
def _parse_timestamp(line: str) -> datetime | None:
    """尝试解析行首的 ISO 8601 时间戳，失败返回 None。"""
    try:
        return datetime.fromisoformat(line.split(' ', 1)[0])
    except (ValueError, IndexError):
        return None

# ---------- 核心函数 ----------
def _filter_log(
    ts: datetime,
    level: str,
    source: str,
    now: datetime | None = None,
) -> bool:
    """按时间、级别和来源过滤日志行。返回 True 表示保留。"""
    if not isinstance(level, str):
        return False
    if level != 'INFO':
        return False
    if source != 'main':
        return False
    if now is None:
        now = datetime.now(timezone.utc)
    if ts > now:
        return False
    return True

# ---------- 入口 ----------
def main() -> int:
    """从 stdin 读取日志行，按规则过滤并输出汇总。"""
    lines = [l.rstrip('\n') for l in sys.stdin if l.strip()]
    now = datetime.now(timezone.utc)

    # 按时间、级别和来源过滤
    filtered = [
        line for line in lines
        if _filter_log(_parse_timestamp(line), line.split(':', 1)[1], 'main')
    ]

    # 输出汇总统计
    print(f"INFO 主线程日志数：{len(filtered)}")
    return 0

if __name__ == '__main__':
    main()

