"""扫描目录下的重复文件（按内容哈希），支持 --dry-run 与 --json 输出。"""
import argparse
import hashlib
import json
import os
from pathlib import Path

def compute_hash(file_path):
    """计算文件的 SHA-256 哈希值。"""
    sha256 = hashlib.sha256()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            sha256.update(chunk)
    return sha256.hexdigest()


def find_duplicates(directory):
    """查找目录下内容相同的文件。返回字典 {hash: [paths]}。"""
    hash_map = {}
    for path in Path(directory).rglob('*'):
        if path.is_file():
            h = compute_hash(path)
            hash_map.setdefault(h, []).append(str(path))


def main():
    parser = argparse.ArgumentParser(description='扫描目录下的重复文件。')
    parser.add_argument('directory', help='要扫描的目录路径')
    parser.add_argument('--dry-run', action='store_true', help='不实际删除，仅显示将要操作的内容')
    parser.add_argument('--json', action='store_true', help='以 JSON 格式输出结果')
    args = parser.parse_args()

    duplicates = find_duplicates(args.directory)
    if not duplicates:
        print(json.dumps({'duplicates': []}, indent=2) if args.json else '未发现重复文件。')
        return

    output = {}
    for h, paths in duplicates.items():
        if len(paths) > 1:
            output[h] = paths

    print(json.dumps(output, indent=2) if args.json else '\n'.join(f'{p} (哈希: {h})' for h, p in list(output.items())[:10]))


if __name__ == '__main__':
    main()
